SELECT job_title, DATE_FORMAT(hire_date, 'yyyy-MM') AS hire_month, ROUND(STDDEV(salary), 2) AS stddev_salary, SUM(CASE WHEN job_title = 'Engineer' THEN 1 ELSE 0 END) AS engineer_count, COUNT(CASE WHEN level = 'L3' THEN 1 END) AS l3_count FROM employees WHERE LENGTH(full_name) > 13 AND email LIKE '%@startup.io' AND is_remote GROUP BY job_title, hire_month HAVING SUM(CASE WHEN job_title = 'Engineer' THEN 1 ELSE 0 END) >= 63 ORDER BY engineer_count ASC
